-- Optional data models for future modules. Run AFTER 001_initial.sql and 003_settings.sql.
-- This migration adds storage, not production-ready integrations or tax calculations.
create table if not exists public.bank_accounts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,iban_last4 text,currency text not null default 'EUR',account_type text not null default 'checking',created_at timestamptz default now());
create table if not exists public.interest_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),interest_account_id uuid references public.interest_accounts(id),value_date date not null,gross_interest numeric(14,2) not null,tax_withheld numeric(14,2) default 0,notes text);
create table if not exists public.insurance_payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),insurance_contract_id uuid references public.insurance_contracts(id),paid_on date,amount numeric(14,2),notes text);
create table if not exists public.properties(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),tax_subject_id uuid references public.tax_subjects(id),name text not null,address text,usage_type text,notes text);
create table if not exists public.loans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),property_id uuid references public.properties(id),lender text not null,balance numeric(14,2),interest_rate numeric(7,4),fixed_until date);
create table if not exists public.platform_settlements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),platform text not null,reference text,period_start date,period_end date,gross_amount numeric(14,2),commission numeric(14,2),payout numeric(14,2),cost_center_id uuid references public.cost_centers(id),status text default 'draft');
create table if not exists public.pension_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),tax_subject_id uuid references public.tax_subjects(id),record_date date,monthly_estimate numeric(14,2),source text,notes text);
do $$ declare t text;begin foreach t in array array['bank_accounts','interest_entries','insurance_payments','properties','loans','platform_settlements','pension_records'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for select to authenticated using(public.member_of(organization_id))',t||'_read',t);execute format('create policy %I on public.%I for insert to authenticated with check(public.can_edit(organization_id))',t||'_insert',t);execute format('create policy %I on public.%I for update to authenticated using(public.can_edit(organization_id)) with check(public.can_edit(organization_id))',t||'_update',t);end loop;end $$;
